@app.route("/process", methods=["POST"])
@auth.login_required
def process():
    user = auth.current_user()
    premium = request.form.get("premium") == "on"
    original, error = validate_upload(request.files.get("file"))
    if error:
        flash(error, "error")
        return redirect(url_for("index"))

    error = check_quota(user, premium)
    if error:
        flash(error, "error")
        return redirect(url_for("index"))
    if storage_usage() > STORAGE_CAP_BYTES:
        flash("服务器存储空间不足，请稍后再试或联系管理员", "error")
        return redirect(url_for("index"))

    mode = "premium" if premium else "normal"
    work_dir = os.path.join(COLLECTED_DIR, str(user["id"]), ts_dir_name())
    os.makedirs(work_dir, exist_ok=True)
    input_path = os.path.join(work_dir, f"original{file_extension(original)}")
    request.files["file"].save(input_path)

    try:
        output_file, payload_text = run_core(input_path, work_dir, mode)
    except CoreBusy:
        flash("当前处理任务较多，请稍后再试（未扣次数）", "error")
        return redirect(url_for("index"))
    except CoreTimeout:
        flash("文件处理超时，请拆分或缩小文件后重试（未扣次数）", "error")
        return redirect(url_for("index"))
    except ValueError:
        flash("不支持的文件类型", "error")
        return redirect(url_for("index"))
    except Exception:
        app.logger.exception("processing failed for user %s", user["id"])
        flash("文件处理失败，请检查文件是否损坏后重试（未扣次数）", "error")
        return redirect(url_for("index"))

    # Charge only after the core produced its output.
    error = charge_user(user, premium)
    if error:
        flash(error, "error")
        return redirect(url_for("index"))

    db.log_usage(user["id"], original, mode, premium)
    session["result"] = {
        "url": url_for("download", user_id=user["id"], ts=os.path.basename(work_dir),
                        name=os.path.basename(output_file)),
        "name": os.path.basename(output_file),
        "chars": len(payload_text),
    }
    return redirect(url_for("index"))


